import os
import sys
import json

EXPENSES_FILE = 'expenses.state'

class ExpenseManager:
    def __init__(self):
        self.expenses = []
        self.load_expenses()

    def load_expenses(self):
        if os.path.exists(EXPENSES_FILE):
            with open(EXPENSES_FILE, 'r') as f:
                self.expenses = json.load(f)

    def add_expense(self, amount, category):
        self.expenses.append({'amount': amount, 'category': category})
        self.save_expenses()

    def save_expenses(self):
        with open(EXPENSES_FILE, 'w') as f:
            json.dump(self.expenses, f)

    def list_expenses(self):
        for expense in self.expenses:
            print(f"{expense['amount']:.2f} {expense['category']}")

    def total_expenses(self):
        total = sum(expense['amount'] for expense in self.expenses)
        print(f"{total:.2f}")

def main():
    manager = ExpenseManager()
    for line in sys.stdin:
        command = line.strip().split()
        if command[0] == 'add':
            amount = float(command[1])
            category = command[2]
            manager.add_expense(amount, category)
        elif command[0] == 'list':
            manager.list_expenses()
        elif command[0] == 'total':
            manager.total_expenses()

if __name__ == '__main__':
    main()

import sys
import json
from decimal import Decimal, getcontext

def load_state(file_path):
    try:
        with open(file_path, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return []

def save_state(file_path, entries):
    with open(file_path, 'w') as f:
        json.dump(entries, f)

def main():
    if len(sys.argv) != 2:
        print("Usage: python expenses.py <state_file_path>", file=sys.stderr)
        sys.exit(1)

    state_file = sys.argv[1]
    entries = load_state(state_file)

    getcontext().prec = 2  # Ensure precision for decimal handling

    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue

        cmd = parts[0].lower()
        if cmd == 'add':
            if len(parts) != 3:
                print("Invalid add command format", file=sys.stderr)
                continue
            try:
                amount = Decimal(parts[1])
                category = parts[2]
                entries.append({'amount': amount, 'category': category})
            except ValueError:
                print("Invalid amount format", file=sys.stderr)
                continue
        elif cmd == 'list':
            for entry in entries:
                print(f"{entry['amount']:.2f} {entry['category']}")
        elif cmd == 'total':
            total = sum(entry['amount'] for entry in entries)
            print(f"{total:.2f}")
        else:
            print(f"Unknown command: {cmd}", file=sys.stderr)

        save_state(state_file, entries)

if __name__ == "__main__":
    main()

import sys
import json

class ExpenseTracker:
    def __init__(self):
        self.entries = []
        self.load_state()

    def load_state(self):
        try:
            with open('expenses.state', 'r') as f:
                self.entries = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError):
            self.entries = []

    def save_state(self):
        with open('expenses.state', 'w') as f:
            json.dump(self.entries, f)

    def add_entry(self, amount, category):
        self.entries.append({'amount': float(amount), 'category': category})
        self.save_state()

    def list_entries(self):
        for entry in self.entries:
            print(f"{entry['amount']:.2f} {entry['category']}")

    def calculate_total(self):
        total = sum(entry['amount'] for entry in self.entries)
        print(f"{total:.2f}")

def main():
    tracker = ExpenseTracker()
    while True:
        try:
            command = input().strip().lower()
            if not command:
                continue
            parts = command.split()
            if parts[0] == 'add':
                if len(parts) != 3:
                    continue
                amount, category = parts[1], parts[2]
                tracker.add_entry(amount, category)
            elif parts[0] == 'list':
                tracker.list_entries()
            elif parts[0] == 'total':
                tracker.calculate_total()
        except EOFError:
            break

if __name__ == "__main__":
    main()

import sys
import json

def load_expenses():
    try:
        with open('expenses.state', 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return []

def save_expenses(expenses):
    with open('expenses.state', 'w') as f:
        json.dump(expenses, f)

def process_command(command):
    parts = command.split()
    if not parts:
        return
    cmd = parts[0].lower()
    if cmd == 'add':
        if len(parts) != 3:
            return
        try:
            amount = float(parts[1])
            if not amount.is_integer() or amount % 1 != 0:
                return
            amount = round(amount, 2)
            category = parts[2]
            expenses.append({'amount': amount, 'category': category})
        except ValueError:
            pass
    elif cmd == 'list':
        for entry in expenses:
            print(f"{entry['amount']:.2f} {entry['category']}")

def main():
    expenses = load_expenses()
    while True:
        try:
            line = sys.stdin.readline().strip()
            if not line:
                break
            process_command(line)
            save_expenses(expenses)
        except EOFError:
            break

if __name__ == "__main__":
    main()

import sys

def main():
    entries = []
    state_file = "expenses.state"

    # Load existing entries if file exists
    if state_file in sys.argv or os.path.exists(state_file):
        with open(state_file, 'r') as f:
            entries = [line.strip() for line in f.readlines()]

    for line in sys.stdin:
        parts = line.strip().split()
        if not parts:
            continue
        cmd = parts[0].lower()
        if cmd == "add":
            if len(parts) < 3:
                continue
            amount = parts[1]
            category = ' '.join(parts[2:])
            entries.append(f"{amount} {category}")
            with open(state_file, 'w') as f:
                f.write('\n'.join(entries))
        elif cmd == "list":
            for entry in entries:
                print(entry)

